from pathlib import Path
p=Path(__file__).resolve().parent.parent
base=p/'engine/world-of-maxxia/src'
def patch(path,old,new,n=1):
 f=base/path
 s=f.read_text()
 if old not in s: raise Exception('Missing '+str(path)+'\n'+old[:200])
 s=s.replace(old,new,n)
 f.write_text(s)
