patch(path,"export type PreparedStyle=typeof STYLES[number];","export type PreparedStyle=string;\nexport interface ClassChoice {id:string;name:string;description:string;attributeBonuses?:Partial<Record<Ability,number>>;starterEquipment?:Partial<Record<'melee'|'ranged'|'body'|'offhand',string|null>>;abilityGrants?:{id:string;minLevel:number}[];}\nexport interface AuthoredStyle {id:string;name:string;description:string;operation:'weapon'|'device'|'natural';requiredTrait:string|null;attackBonus:number;attackBonusAtVeteran:number;damageBonus:number;damageBonusAtMilestone:number;damageBonusAtMilestoneReplacesBase:boolean;ignoreDefense:number;damageType:'physical'|'lightning';dice:string;diceAtMilestone:string|null;diceAtVeteran:string|null;defenseBonus:number;defenseAtVeteran:number;}")
patch(path,"preparedStyles:PreparedStyle[];}","preparedStyles:PreparedStyle[];styleDefinitions?:AuthoredStyle[];abilityGrants?:{id:string;minLevel:number}[];creationChoices?:ClassChoice[];}")
patch(path,"  for(const [field,options,max] of [['equipmentTags',EQUIPMENT_TAGS,11],['traits',CLASS_TRAITS,4],['preparedStyles',STYLES,8]] as const){\n   const a=v[field];if(!Array.isArray(a)||a.length>max||(field!=='traits'&&a.length===0)||new Set(a).size!==a.length||a.some(x=>typeof x!=='string'||!(options as readonly string[]).includes(x)))fail('E_LIST',p+'.'+field,'Unsupported or duplicate tag/trait/style.');\n  }", """  for(const [field,options,max] of [['equipmentTags',EQUIPMENT_TAGS,11],['traits',CLASS_TRAITS,12],['preparedStyles',STYLES,12]] as const){
   const a=v[field];if(!Array.isArray(a)||a.length>max||(field!=='traits'&&a.length===0)||new Set(a).size!==a.length||a.some(x=>typeof x!=='string'||(field==='equipmentTags'?! (options as readonly string[]).includes(x):field==='traits'?!((options as readonly string[]).includes(x)||/^[a-z][a-z0-9_]{0,47}:trait:[a-z][a-z0-9_]{0,79}$/.test(x)):!((options as readonly string[]).includes(x)||/^[a-z][a-z0-9_]{0,47}:style:[a-z][a-z0-9_]{0,79}$/.test(x))))fail('E_LIST',p+'.'+field,'Unsupported or duplicate tag/trait/style.');
  }
  const abilityId=/^[a-z][a-z0-9_]{0,47}:ability:[a-z][a-z0-9_]{0,79}$/;
  const validateGrants=(raw:unknown,path:string)=>{if(raw===undefined)return;if(!Array.isArray(raw)||raw.length>32||new Set(raw.map(x=>x?.id)).size!==raw.length||raw.some(x=>!isRecord(x)||Object.keys(x).sort().join('|')!=='id|minLevel'||!abilityId.test(String(x.id))||!Number.isInteger(x.minLevel)||x.minLevel<1||x.minLevel>20))fail('E_GRANTS',path,'Invalid class/choice ability grant.');};
  validateGrants(v.abilityGrants,p+'.abilityGrants');
  if(v.creationChoices!==undefined){if(!Array.isArray(v.creationChoices)||v.creationChoices.length<1||v.creationChoices.length>12||new Set(v.creationChoices.map(x=>x?.id)).size!==v.creationChoices.length)fail('E_CHOICES',p+'.creationChoices','Invalid choices.');
   for(const [j,ch] of v.creationChoices.entries()){const at=p+`.creationChoices[${j}]`;if(!isRecord(ch)||Object.keys(ch).some(k=>!['id','name','description','attributeBonuses','starterEquipment','abilityGrants'].includes(k))||typeof ch.id!=='string'||!/^[a-z][a-z0-9_]{0,79}$/.test(ch.id)||typeof ch.name!=='string'||!ch.name.trim()||ch.name.length>100||typeof ch.description!=='string'||ch.description.length>500)fail('E_CHOICES',at,'Invalid choice identity');if(ch.attributeBonuses!==undefined&&(!isRecord(ch.attributeBonuses)||Object.entries(ch.attributeBonuses).some(([k,n])=>!ABILITIES.includes(k as Ability)||!Number.isInteger(n)||n< -3||n>3)))fail('E_CHOICES',at+'.attributeBonuses','Invalid choice bonus');validateGrants(ch.abilityGrants,at+'.abilityGrants');if(ch.starterEquipment!==undefined&&(!isRecord(ch.starterEquipment)||Object.entries(ch.starterEquipment).some(([slot,id])=>!['melee','ranged','body','offhand'].includes(slot)||(id!==null&&(typeof id!=='string'||!/^([a-z][a-z0-9_]{0,47}:item:[a-z][a-z0-9_]{0,79}|item_[a-z0-9_]{1,70})$/.test(id))))))fail('E_CHOICES',at+'.starterEquipment','Invalid starting item');}
  }
  if(v.styleDefinitions!==undefined){if(!Array.isArray(v.styleDefinitions)||v.styleDefinitions.length>12||new Set(v.styleDefinitions.map(x=>x?.id)).size!==v.styleDefinitions.length)fail('E_STYLE',p+'.styleDefinitions','Invalid style definitions');for(const [j,s] of v.styleDefinitions.entries()){const at=p+`.styleDefinitions[${j}]`;if(!isRecord(s)||Object.keys(s).sort().join('|')!==['attackBonus','attackBonusAtVeteran','damageBonus','damageBonusAtMilestone','damageBonusAtMilestoneReplacesBase','damageType','defenseAtVeteran','defenseBonus','description','dice','diceAtMilestone','diceAtVeteran','id','ignoreDefense','name','operation','requiredTrait'].sort().join('|')||!v.preparedStyles.includes(s.id)||!String(s.id).startsWith(String(v.id).split(':')[0]+':style:')||!['weapon','device','natural'].includes(String(s.operation))||!(s.requiredTrait===null||(v.traits as string[]).includes(s.requiredTrait as string))||!['physical','lightning'].includes(String(s.damageType))||typeof s.name!=='string'||!s.name.trim()||s.name.length>100||typeof s.description!=='string'||s.description.length>500||typeof s.damageBonusAtMilestoneReplacesBase!=='boolean'||['attackBonus','attackBonusAtVeteran','damageBonus','damageBonusAtMilestone','ignoreDefense','defenseBonus','defenseAtVeteran'].some(k=>!Number.isInteger(s[k])||s[k]< (k==='attackBonus'?-20:0)||s[k]>20)||['dice','diceAtMilestone','diceAtVeteran'].some(k=>s[k]!==null&&(typeof s[k]!=='string'||!/^(?:[1-9][0-9]?d(?:4|6|8|10|12|20)|[1-9][0-9]?)$/.test(s[k] as string)))||s.dice===null)fail('E_STYLE',at,'Invalid authored prepared style');}}
  const custom=(v.preparedStyles as string[]).filter(x=>x.includes(':'));if(custom.some(id=>!(v.styleDefinitions as {id:string}[]|undefined)?.some(s=>s.id===id))||(v.styleDefinitions as {id:string}[]|undefined)?.some(s=>!custom.includes(s.id)))fail('E_STYLE',p+'.preparedStyles','Missing/unused authored style definition');
""")
